// @param float _PosterizeLevels = 6 [2 .. 16]
// @param float _PixelSize = 4 [1 .. 32]
// @param float _DitherStrength = 1.0 [0 .. 1]

static const float BayerMatrix[16] = {
     0.0,  8.0,  2.0, 10.0,
    12.0,  4.0, 14.0,  6.0,
     3.0, 11.0,  1.0,  9.0,
    15.0,  7.0, 13.0,  5.0
};

float SampleBayer(float2 pixelCoord) {
    int2 cell = int2(pixelCoord - 4.0 * floor(pixelCoord / 4.0));
    return (BayerMatrix[cell.y * 4 + cell.x] + 0.5) / 16.0 - 0.5;
}

float4 ApplyFX(float2 uv, float4 color) {
    float2 canvasSize = max(_CanvasSize.xy, float2(1.0, 1.0));
    float pixelSize = max(1.0, floor(_PixelSize));

    // Sample each block at its center, including partial blocks at the canvas edges.
    float2 canvasPixel = clamp(uv * canvasSize, 0.0, canvasSize - 0.5);
    float2 pixelCoord = floor(canvasPixel / pixelSize);
    float2 blockStart = pixelCoord * pixelSize;
    float2 blockEnd = min(blockStart + pixelSize, canvasSize);
    float2 snappedUV = (blockStart + blockEnd) * 0.5 / canvasSize;
    float4 sampled = SampleInput(snappedUV);

    // Centered Bayer thresholds: zero mean, one threshold per coarse block.
    float bayer = SampleBayer(pixelCoord) * _DitherStrength;

    // Posterization with dithering.
    float levels = max(2.0, floor(_PosterizeLevels));
    float steps = levels - 1.0;
    float3 dithered = sampled.rgb + bayer / steps;
    float3 posterized = floor(dithered * steps + 0.5) / steps;
    return float4(saturate(posterized), sampled.a);
}
